parameters.jsCode:
// Arma la TRAZA para el Juez: query + contexto Airtable + contexto de herramientas (intermediate steps) + respuesta propuesta
// y estima tokens/costo del Ejecutor en ESTE intento (caracteres / 4; se valida contra OpenRouter Activity)
const r = $input.first().json;                                   // salida de ③
const ag = $('AI Agent – Asistente Pañol (canal Voz)').last().json;
const out = ag.output || {};
const steps = Array.isArray(ag.intermediateSteps) ? ag.intermediateSteps : [];
const mem = $('Leer Memoria (Airtable · Memoria_Panol)').first().json || {};
const norm = $('Normalizar entrada (Telegram)').first().json;
const uni = $('Unificar consulta (voz / texto)').first().json;
let intento = 0;
try { if ($('Preparar reintento (Self-Healing)').isExecuted) intento = Number($('Preparar reintento (Self-Healing)').last().json.intento) || 0; } catch (e) {}

const obs = steps.map((s, i) => {
  const tool = (s.action && s.action.tool) || 'tool';
  const inp = JSON.stringify((s.action && s.action.toolInput) ?? '').slice(0, 300);
  let o = s.observation; if (typeof o !== 'string') o = JSON.stringify(o);
  return `#${i + 1} ${tool}(${inp}) → ${String(o).slice(0, 1800)}`;
});
const contexto_recuperado = obs.length ? obs.join('\n\n').slice(0, 6000) : 'El agente no consultó herramientas en este intento.';
const contexto_airtable = {
  estado_ultimo_caso: mem.Estado_Caso || 'Sin historial',
  resumen_previo: mem.Resumen_Consolidado || 'Sin historial',
  accion_pendiente: mem.Accion_Requerida || 'Ninguna'
};

// Criticidad → umbral dinámico del Juez (5 en crítica, 4 en normal)
const alta = ['gestion_material', 'consulta_comercial'].includes(out.intent) ||
  (out.intent === 'consulta_procedimiento' && /cr[ií]tic|segur|bloque|epp|loto|monto|\$|palo|mill[oó]n|fuera de horario|domingo|feriado|noche|guardia/i.test(uni.texto || ''));

// Estimación de tokens del Ejecutor
const SYS = 6728;
const userChars = String(uni.texto || '').length + 650 + (intento ? 700 : 0);
const llamadas = steps.length + 1;
let inChars = llamadas * (SYS + userChars);
let acum = 0; for (const o of obs) { acum += o.length; inChars += acum; }
const outChars = JSON.stringify(out).length + steps.length * 150;
const tIn = Math.round(inChars / 4), tOut = Math.round(outChars / 4);
const PRECIOS = { 'openai/gpt-4o-mini': [0.15, 0.60], 'openai/gpt-4.1-mini': [0.40, 1.60] };   // USD / 1M tokens – verificar
const p = PRECIOS[norm.modelo_ejecutor] || [0, 0];

return [{ json: {
  caso_id: norm.caso_id, arquitectura: norm.arquitectura, modelo_ejecutor: norm.modelo_ejecutor, intento,
  session_id: r.session_id, nombre: r.nombre, canal: r.canal,
  consulta: String(uni.texto || '').slice(0, 1000),
  contexto_airtable: JSON.stringify(contexto_airtable),
  contexto_recuperado,
  respuesta_agente: JSON.stringify({ respuesta: r.respuesta_texto, intent: out.intent, dato_solicitado: out.dato_solicitado,
    evidencia: out.evidencia, fuente_rag: r.fuente_rag, sin_respuesta_en_manual: r.sin_respuesta_en_manual,
    requiere_revision: r.requiere_revision, codigo_sap: r.codigo_sap, material: r.material }),
  respuesta_texto: r.respuesta_texto, respuesta_voz: r.respuesta_voz, requiere_revision: r.requiere_revision,
  criticidad: alta ? 'alta' : 'normal', n_tools: steps.length,
  tokens_ejecutor: tIn + tOut, coste_ejecutor_usd: Number(((tIn * p[0] + tOut * p[1]) / 1e6).toFixed(6)),
  latencia_agente_s: Number(((Date.now() - Number(norm.t0)) / 1000).toFixed(1))
} }];
